SNIPPET.JAVASCRIPT:
function factorial(n) {
    return n === 1 
           ? 1
           : n * factorial(n - 1);
}

BILINGUAL.EN:
Once again, we can recast our description as a
procedure function
for computing factorials:

SNIPPET.JAVASCRIPT:
function factorial(n) {
    function iter(product, counter) {
        return counter > n 
               ? product
               : iter(counter * product,
                      counter + 1);
    }
    return iter(1, 1);
}

function factorial(n) {
    return fact_iter(1, 1, n);
}
function fact_iter(product, counter, max_count) {
    return counter > max_count
           ? product
           : fact_iter(counter * product,
                       counter + 1,
                       max_count);
}

function inc(x) {
    return x + 1;
}
function dec(x) {
    return x - 1;
}

function plus(a, b) {
    return a === 0 ? b : inc(plus(dec(a), b)); 
}

function plus(a, b) {
    return a === 0 ? b : plus(dec(a), inc(b));
}

function A(x, y) {
    return y === 0
           ? 0
           : x === 0
           ? 2 * y
           : y === 1
           ? 2
           : A(x - 1, A(x, y - 1));
}

function f(n) {
    return A(0, n);
}
function g(n) {
    return A(1, n);
}
function h(n) {
    return A(2, n);
}
function k(n) {
   return 5 * n * n;
}
